  const root=document.querySelector('.support-chat-admin[data-ready="1"]'); if(!root)return;
  const csrfMeta=document.querySelector('meta[name="csrf-token-hash"]'); let csrf=csrfMeta?.content||''; let selected=0,lastMessage=0,queueBusy=false,messageBusy=false;
  const queue=document.getElementById('chatQueue'),messages=document.getElementById('chatMessages'),reply=document.getElementById('chatReply'),sendButton=document.querySelector('#chatReplyForm button'),claim=document.getElementById('chatClaim'),close=document.getElementById('chatClose'),toast=document.getElementById('chatToast'),confirmDialog=document.getElementById('chatConfirm');
  function showToast(message,error=false){toast.textContent=message;toast.classList.toggle('is-error',error);toast.hidden=false;window.clearTimeout(showToast.timer);showToast.timer=window.setTimeout(()=>toast.hidden=true,4200);}
  function confirmAction(message){return new Promise(resolve=>{confirmDialog.querySelector('p').textContent=message;confirmDialog.addEventListener('close',()=>resolve(confirmDialog.returnValue==='confirm'),{once:true});confirmDialog.showModal();});}
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const freePreset=document.getElementById('useOpenRouterFree');
  freePreset?.addEventListener('click',()=>{document.getElementById('chatProviderEndpoint').value='https://openrouter.ai/api/v1/chat/completions';document.getElementById('chatProviderModel').value='openrouter/free';document.getElementById('chatProviderEndpoint').focus();});
  async function request(url,options={}){const headers=new Headers(options.headers||{});if(options.method==='POST'){headers.set('X-CSRF-TOKEN',csrf);headers.set('Content-Type','application/json');}const response=await fetch(url,{...options,headers,credentials:'same-origin',cache:'no-store'});const data=await response.json();if(data.csrfHash){csrf=data.csrfHash;const meta=document.querySelector('meta[name="csrf-token-hash"]');if(meta)meta.content=csrf;}if(!response.ok||!data.success)throw new Error(data.message||'Permintaan gagal');return data;}
  function drawQueue(items){document.getElementById('chatQueueCount').textContent=String(items.length);if(!items.length){queue.innerHTML='<p class="support-chat-muted">Belum ada percakapan aktif.</p>';return;}queue.innerHTML=items.map(x=>`<button type="button" class="support-chat-conversation ${Number(x.id)===selected?'is-selected':''} ${x.status==='human_waiting'?'is-waiting':''}" data-id="${Number(x.id)}"><strong>${x.status==='human_waiting'?'Perlu staf':x.status==='human'?'Dilayani staf':'Assistant'}</strong><span>${esc(x.customer_email||'Pelanggan tamu')} · ${esc(x.context_product_id||'')}</span><small>${esc(x.last_body||'Belum ada pesan')}<br>${esc(x.last_message_at||'')}</small></button>`).join('');}
  async function loadQueue(){if(queueBusy||document.hidden)return;queueBusy=true;try{const d=await request('/admin/support-chat/queue');drawQueue(d.items||[]);}catch(e){queue.innerHTML=`<p class="support-chat-muted">${esc(e.message)}</p>`;}finally{queueBusy=false;}}
  function drawMessages(items){if(!items.length&&lastMessage===0){messages.innerHTML='<p class="support-chat-muted">Belum ada pesan.</p>';return;}for(const m of items){lastMessage=Math.max(lastMessage,Number(m.id)||0);const el=document.createElement('div');el.className='support-chat-message '+(m.sender_type==='visitor'?'is-visitor':m.sender_type==='system'?'is-system':'');el.innerHTML=`${esc(m.body)}<small>${esc(m.sender_type==='admin'?m.sender_id||'Admin':m.sender_type)} · ${esc(m.created_at)}</small>`;messages.appendChild(el);}messages.scrollTop=messages.scrollHeight;}
  async function loadMessages(){if(!selected||messageBusy||document.hidden)return;messageBusy=true;try{const d=await request(`/admin/support-chat/messages/${selected}?after=${lastMessage}`);drawMessages(d.messages||[]);document.getElementById('chatThreadTitle').textContent=d.conversation.customer_email||'Pelanggan tamu';document.getElementById('chatThreadMeta').textContent=`${d.conversation.status} · ${d.conversation.context_product_id?'Produk '+d.conversation.context_product_id:'Tanpa konteks produk'}`;}catch(e){document.getElementById('chatThreadMeta').textContent=e.message;}finally{messageBusy=false;}}
  function drawFeedback(items){const list=document.getElementById('chatFeedbackList');list.replaceChildren();if(!items.length){const empty=document.createElement('p');empty.className='support-chat-muted';empty.textContent='Belum ada penilaian dari pelanggan.';list.append(empty);return;}for(const item of items){const row=document.createElement('article'),score=document.createElement('strong'),identity=document.createElement('span'),time=document.createElement('time');score.textContent=`${Number(item.rating)||0} / 5`;identity.textContent=[item.customer_email||'Pelanggan tamu',item.context_product_id||''].filter(Boolean).join(' · ');time.textContent=item.rated_at||'';row.append(score,identity,time);list.append(row);}}
  async function loadFeedback(){if(document.hidden)return;try{const data=await request('/admin/support-chat/feedback');document.getElementById('chatFeedbackCount').textContent=String(data.stats?.count||0);document.getElementById('chatFeedbackAverage').textContent=data.stats?.average==null?'—':Number(data.stats.average).toLocaleString('id-ID',{minimumFractionDigits:1,maximumFractionDigits:1});drawFeedback(data.items||[]);}catch(error){showToast(error.message,true);}}
  document.getElementById('refreshChatFeedback')?.addEventListener('click',loadFeedback);
  queue.addEventListener('click',e=>{const button=e.target.closest('[data-id]');if(!button)return;selected=Number(button.dataset.id);lastMessage=0;messages.innerHTML='';reply.disabled=false;sendButton.disabled=false;claim.disabled=false;close.disabled=false;loadQueue();loadMessages();});
  document.getElementById('chatReplyForm').addEventListener('submit',async e=>{e.preventDefault();if(!selected||!reply.value.trim())return;sendButton.disabled=true;try{await request(`/admin/support-chat/reply/${selected}`,{method:'POST',body:JSON.stringify({message:reply.value.trim()})});reply.value='';await loadMessages();await loadQueue();}catch(err){showToast(err.message,true);}finally{sendButton.disabled=false;}});
  claim.addEventListener('click',async()=>{if(selected){try{await request(`/admin/support-chat/claim/${selected}`,{method:'POST',body:'{}'});await loadQueue();await loadMessages();showToast('Percakapan masuk ke penanganan Anda.');}catch(e){showToast(e.message,true);}}});
  close.addEventListener('click',async()=>{if(selected&&await confirmAction('Tutup percakapan ini?')){try{await request(`/admin/support-chat/close/${selected}`,{method:'POST',body:'{}'});selected=0;lastMessage=0;messages.innerHTML='<p class="support-chat-muted">Pilih percakapan di antrean.</p>';reply.disabled=true;sendButton.disabled=true;claim.disabled=true;close.disabled=true;await loadQueue();showToast('Percakapan ditutup.');}catch(e){showToast(e.message,true);}}});
  document.querySelectorAll('[data-confirm]').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();if(await confirmAction(form.dataset.confirm))form.submit();}));
  document.querySelectorAll('.support-chat-edit-knowledge').forEach(button=>button.addEventListener('click',()=>{const data=JSON.parse(button.closest('[data-knowledge]').dataset.knowledge);const form=document.getElementById('knowledgeForm');form.elements.id.value=data.id;form.elements.title.value=data.title;form.elements.content.value=data.content;form.elements.source_url.value=data.source_url||'';form.elements.is_published.checked=String(data.is_published)==='1';form.scrollIntoView({behavior:'smooth',block:'center'});}));
  document.querySelectorAll('.support-chat-spec-row').forEach(button=>button.addEventListener('click',()=>{const data=JSON.parse(button.dataset.spec);const form=document.querySelector('.support-chat-spec-form');form.elements.product_id.value=data.product_id;form.elements.colors.value=data.colors||'';form.elements.materials.value=data.materials||'';form.elements.dimensions.value=data.dimensions||'';form.elements.keywords.value=data.keywords||'';form.scrollIntoView({behavior:'smooth',block:'center'});}));
  loadQueue();loadFeedback();setInterval(loadQueue,10000);setInterval(loadMessages,5000);setInterval(loadFeedback,30000);
})();
</script>
<?= $this->endSection(); ?>
